commit 267e330b078c08d58fd0717ab1c1e4de3ccf2bb7
Author:     Tim <tim.koehler90@googlemail.com>
AuthorDate: Mon Nov 9 14:21:55 2026 +0100
Commit:     Tim <tim.koehler90@googlemail.com>
CommitDate: Mon Nov 9 14:21:55 2026 +0100

    m5-app-design-workspace: F2 fix 4.24 iOS in-set target=_blank link loads in the existing web view

diff --git a/app/preview/src/commonMain/kotlin/eu/weaver/app/preview/NewWindowRouting.kt b/app/preview/src/commonMain/kotlin/eu/weaver/app/preview/NewWindowRouting.kt
index 08b24b7b..c7a2087e 100644
--- a/app/preview/src/commonMain/kotlin/eu/weaver/app/preview/NewWindowRouting.kt
+++ b/app/preview/src/commonMain/kotlin/eu/weaver/app/preview/NewWindowRouting.kt
@@ -23,6 +23,12 @@ internal sealed interface NewWindowAction {
 internal object NewWindowRouting {
     /** A user-activated request that names a page is a link decided as a main-frame one; any other request is a popup. */
     fun decide(targetUrl: String?, gesture: Boolean, guards: Set<Guard>, origin: String, pages: PageSet): NewWindowAction = when {
+        Guard.NavigationVeto in guards && gesture && !targetUrl.isNullOrEmpty() && !targetUrl.startsWith("about:") ->
+            when (val decision = LinkPolicy.classify(targetUrl, gesture = true, origin, pages)) {
+                is LinkDecision.InPreview -> NewWindowAction.LoadInPlace(targetUrl)
+                is LinkDecision.Confirm -> NewWindowAction.Confirm(decision.url)
+                is LinkDecision.Drop -> NewWindowAction.Drop(decision.reason)
+            }
         Guard.Popups in guards -> NewWindowAction.Refuse
         else -> NewWindowAction.Allow
     }
diff --git a/app/preview/src/iosMain/kotlin/eu/weaver/app/preview/WkPreviewEngine.kt b/app/preview/src/iosMain/kotlin/eu/weaver/app/preview/WkPreviewEngine.kt
index d1ab58e6..5b84b704 100644
--- a/app/preview/src/iosMain/kotlin/eu/weaver/app/preview/WkPreviewEngine.kt
+++ b/app/preview/src/iosMain/kotlin/eu/weaver/app/preview/WkPreviewEngine.kt
@@ -361,11 +361,28 @@ internal class WkPreviewEngine(
      */
     private inner class PreviewUiDelegate : NSObject(), WKUIDelegateProtocol {
         override fun webView(webView: WKWebView, createWebViewWithConfiguration: WKWebViewConfiguration, forNavigationAction: WKNavigationAction, windowFeatures: WKWindowFeatures): WKWebView? {
-            if (on(Guard.Popups)) {
-                refused(Reason.Popup)
-                return null
+            val gesture = forNavigationAction.navigationType == WKNavigationTypeLinkActivated
+            when (val action = NewWindowRouting.decide(forNavigationAction.request.URL?.absoluteString, gesture, config.guards, origin, pages)) {
+                NewWindowAction.Refuse -> {
+                    refused(Reason.Popup)
+                    return null
+                }
+                NewWindowAction.Allow -> Unit
+                // A user-activated `target=_blank` link: the window is never opened, the link is decided as a main-frame one (D-3, D-7).
+                is NewWindowAction.LoadInPlace -> {
+                    webView.loadRequest(NSURLRequest(NSURL(string = action.url)))
+                    return null
+                }
+                is NewWindowAction.Confirm -> {
+                    emit(PreviewEvent.LinkRequested(action.url, true))
+                    return null
+                }
+                is NewWindowAction.Drop -> {
+                    refused(action.reason)
+                    return null
+                }
             }
-            if (forNavigationAction.navigationType == WKNavigationTypeLinkActivated) observe("pop-target-blank")
+            if (gesture) observe("pop-target-blank")
             val window = WKWebView(frame = CGRectZero.readValue(), configuration = createWebViewWithConfiguration)
             windows.add(window)
             return window

