commit cf96f70270f4a8867ac585bc7e5a73a2f6bfa358
Author:     Tim <tim.koehler90@googlemail.com>
AuthorDate: Mon Nov 9 14:24:57 2026 +0100
Commit:     Tim <tim.koehler90@googlemail.com>
CommitDate: Mon Nov 9 14:24:57 2026 +0100

    m5-app-design-workspace: F2 fix 4.23 Android Stop ends within an app-owned deadline (BoundedStop scheduled on the main looper)

diff --git a/app/preview/src/androidMain/kotlin/eu/weaver/app/preview/WebViewEngine.kt b/app/preview/src/androidMain/kotlin/eu/weaver/app/preview/WebViewEngine.kt
index 70788156..086c7022 100644
--- a/app/preview/src/androidMain/kotlin/eu/weaver/app/preview/WebViewEngine.kt
+++ b/app/preview/src/androidMain/kotlin/eu/weaver/app/preview/WebViewEngine.kt
@@ -103,11 +103,14 @@ internal class WebViewEngine(
         val open = view
         if (open != null && on(Guard.StateClearing) && open.url?.let(::isOwn) == true) {
             // The next open waits for this close, whose clearing runs asynchronously in the engine and would otherwise delete its first writes.
-            Closing.acquire()
-            clearPageStorage(open) {
-                finishStop()
-                Closing.release()
-            }
+            // The deadline is the app's own: a renderer busy in a script never answers the clearing's callbacks.
+            BoundedStop(
