         assertEquals(state == Availability.Ready, Files.exists(mark), "state: $state; marker: ${Files.exists(mark)}")
     }
 }
+
+/** design.md D-4 amendment 14 (W2-B1): a cancel that arrives after the install committed publishes the installed engine. */
+class DesktopCommitWinsTest {
+    @Test
+    fun aCancelAfterTheCommitAndBeforeTheOutcomeIsPublishedLeavesReadyAndTheInstallOnDisk() = runBlocking {
+        val dir = Files.createTempDirectory("weaver-commit-wins")
+        val gz = java.io.ByteArrayOutputStream()
+        // An empty tar archive (two zero blocks), gzipped: the smallest `.tar.gz` the extractor accepts.
+        java.util.zip.GZIPOutputStream(gz).use { it.write(ByteArray(1024)) }
+        val zipped = java.io.ByteArrayOutputStream()
+        java.util.zip.ZipOutputStream(zipped).use { zip ->
+            zip.putNextEntry(java.util.zip.ZipEntry("engine-test.tar.gz"))
+            zip.write(gz.toByteArray())
+            zip.closeEntry()
+        }
+        val bytes = zipped.toByteArray()
+        Files.write(dir.resolve("engine-test.jar"), bytes)
+        val sha = java.security.MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }
+        val pin = EnginePin(
+            platform = "test", release = "0", artifact = "engine-test.jar", urls = listOf("https://127.0.0.1:1/never.jar"),
+            size = bytes.size.toLong(), sha256 = sha, installedBytes = 1L,
+        )
+        val committed = CountDownLatch(1)
+        val proceed = CountDownLatch(1)
+        val installer = EngineInstaller.create(pin, dir) {
+            committed.countDown()
+            check(proceed.await(10, TimeUnit.SECONDS)) { "the test never released the worker" }
+        }
+        val engines = DesktopPreviewEngines(installer)
+        val acquiring = launch(Dispatchers.Default) { engines.acquire() }
+        try {
+            assertTrue(withContext(Dispatchers.IO) { committed.await(10, TimeUnit.SECONDS) }, "the worker crossed the commit")
+            assertTrue(Files.exists(dir.resolve("engine/install.lock")) && Files.exists(dir.resolve("engine/.weaver-verified")), "both markers are written")
+            acquiring.cancel()
+        } finally {
+            proceed.countDown()
+        }
+        acquiring.join()
+        assertEquals(Availability.Ready, engines.availability.value, "a committed install is never reported as cancelled")
+        assertTrue(installer.isInstalled(), "the installation is on disk")
+    }
+}
