package eu.weaver.app.preview

/** The closes in flight in this process: the engine clears a process-wide jar asynchronously, so an open waits for them. Main thread only. */
internal class ClosingBarrier {
    private var count = 0
    private val waiting = mutableListOf<() -> Unit>()

    fun acquire() {
        count++
    }

    fun release() {
        count--
        if (count == 0) {
            val ready = waiting.toList()
            waiting.clear()
            ready.forEach { it() }
        }
    }

    fun whenIdle(block: () -> Unit) {
        if (count == 0) block() else waiting += block
    }
}

/**
 * A Stop that ends within an app-owned deadline (spec "Stop ends the engine whatever the renderer does"). The clearing of the
 * page's storage runs in the page's own realm and answers through a callback a busy renderer never makes, so the deadline is
 * scheduled by the app when [begin] is called, not from inside that callback. When the clearing completes first, [finish] runs
 * and [barrier] is released. When the deadline comes first the renderer is unresponsive: [terminateRenderer] ends its process
 * (a script that never returns would otherwise keep serving the next open, which shares the renderer), and [finish] and the
 * barrier's release wait for [rendererGone], or for [rendererWaitMs] when it never comes, so a queued open always gets a fresh
 * renderer. [terminateRenderer] answers whether a termination was requested; with false nothing is awaited. [finish] runs and
 * the barrier is released exactly once; later events are ignored. Main thread only.
 */
internal class BoundedStop(
    private val barrier: ClosingBarrier,
    private val deadlineMs: Long,
    private val rendererWaitMs: Long,
    private val scheduleAfter: (Long, () -> Unit) -> Unit,
    private val clear: (BoundedStop) -> Unit,
    private val terminateRenderer: () -> Boolean,
    private val finish: () -> Unit,
) {
    var settled = false
        private set

    /** True from the deadline on when the renderer was found unresponsive: a completion of the clearing no longer counts. */
    var expired = false
        private set
    private var begun = false

    fun begin() {
        if (begun) return
        begun = true
        barrier.acquire()
        scheduleAfter(deadlineMs) { expire() }
        clear(this)
    }

    /** The clearing completed: the first call finishes the stop and releases the barrier; later calls change nothing, and none counts after the deadline. */
    fun settle() {
        if (!expired) conclude()
    }

    /** The renderer process the stop terminated is gone: the engine may be destroyed and the next open may bind to a fresh renderer. */
    fun rendererGone() {
        if (expired) conclude()
    }

    private fun expire() {
        if (settled || expired) return
        expired = true
        if (terminateRenderer()) scheduleAfter(rendererWaitMs) { conclude() } else conclude()
    }

    private fun conclude() {
        if (settled) return
        settled = true
        try {
            finish()
        } finally {
            barrier.release()
        }
    }
}

