override fun reload() = onMain { view?.reload() }

override fun stop() = onMain {
    if (stopped) return@onMain
    stopped = true
    val open = view
    if (open != null && on(Guard.StateClearing) && open.url?.let(::isOwn) == true) {
        // The next open waits for this close, whose clearing runs asynchronously in the engine and would otherwise delete its first writes.
        // The deadline is the app's own: a renderer busy in a script never answers the clearing's callbacks.
        // At the deadline the clearing has not completed, so the renderer is unresponsive: its process is terminated (it is the
        // only WebView of the product app, so no other view is affected), because the next open would otherwise share it.
        val bounded = BoundedStop(
            barrier = Closing,
            deadlineMs = CLEAR_WAIT_MS,
            rendererWaitMs = RENDERER_WAIT_MS,
            scheduleAfter = { delay, block -> main.postDelayed({ block() }, delay) },
            clear = { bounded -> clearPageStorage(open, bounded) },
            terminateRenderer = { open.webViewRenderProcess?.terminate() == true },
            finish = ::finishStop,
        )
        stopping = bounded
        bounded.begin()
    } else {
        finishStop()
    }
}

private fun finishStop() {
    teardown()
    stateFlow.value = PreviewState.Stopped
    log.record(PreviewLogEvent.StateChanged(PreviewLogState.Stopped))
}

/**
 * `WebStorage.deleteAllData` is asynchronous and leaves the Cache API entries of the origin (measured), so the app also deletes
 * the page's storage in the page's own realm with its own script and polls until the deletion ran or [stop] settled (at the
 * deadline the app scheduled). The script reads nothing from the page and installs no channel.
 */
private fun clearPageStorage(web: WebView, stop: BoundedStop) {
    WebStorage.getInstance().deleteAllData()
    web.evaluateJavascript(CLEAR_PAGE_STORAGE_SCRIPT, null)
    fun poll() {
        if (stop.settled || stop.expired) return
        web.evaluateJavascript("window.__weaverStorageCleared === 1") { finished ->
            if (finished == "true") stop.settle() else if (!stop.settled && !stop.expired) main.postDelayed({ poll() }, CLEAR_POLL_MS)
        }
    }
    poll()
}

@Composable
override fun Surface(modifier: Modifier) {
    AndroidView(factory = { context -> openView(context) }, modifier = modifier)
}

/**
 * The surface is a container the `WebView` is added to once no close is in flight: a `WebView` created earlier would bind to the
 * renderer process of a closing preview, and the termination at that preview's Stop deadline would end the new page with it.
 */
private fun openView(context: Context): View {
    val existing = host
    if (existing != null) return existing
    val container = FrameLayout(context)
    host = container
    if (stopped) return container
    log.record(PreviewLogEvent.StateChanged(PreviewLogState.Loading))
    Closing.whenIdle {
        if (on(Guard.StateClearing)) {
            // A fresh preview starts on an empty jar, whatever an earlier open or another view left in it.
            CookieManager.getInstance().removeAllCookies { main.post { attach(container, context) } }
        } else {
            attach(container, context)
        }
    }
    return container
}

private fun attach(container: FrameLayout, context: Context) {
    if (stopped || view != null || host !== container) return
    val web = createView(context)
    container.addView(web, FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT))
    web.loadUrl(pendingUrl)
}

@SuppressLint("SetJavaScriptEnabled")
@Suppress("DEPRECATION")
private fun createView(context: Context): WebView {
    WebView.setWebContentsDebuggingEnabled(false)
    val web = WebView(context)
    view = web
    web.settings.apply {
        javaScriptEnabled = true
        domStorageEnabled = true
        allowFileAccess = false
        allowContentAccess = false

