/** Destroys the views and, with the guard in force, the state they leave in the process-wide jar (design.md D-7). */
private fun teardown() {
    val open = view
    view = null
    if (open != null) {
        host?.removeView(open)
        open.stopLoading()
        open.clearCache(true)
        open.clearHistory()
        open.webViewClient = WebViewClient()
        open.webChromeClient = null
        open.destroy()
    }
    for (popup in popups) popup.destroy()
    popups.clear()
    if (on(Guard.StateClearing)) {
        Closing.acquire()
        WebStorage.getInstance().deleteAllData()
        CookieManager.getInstance().removeAllCookies {
            CookieManager.getInstance().flush()
            Closing.release()
        }
    }
}

private fun crashed() = onMain {
    if (stopped) return@onMain
    teardown()
    stateFlow.value = PreviewState.Crashed
    log.record(PreviewLogEvent.StateChanged(PreviewLogState.Crashed))
}

private inline fun onMain(crossinline block: () -> Unit) {
    if (Looper.myLooper() === Looper.getMainLooper()) block() else main.post { block() }
}

